local dkjson = require "lib/dkjson"
local files = require "lib/io"
local Database = {}
Database.__index = Database

function Database:init(databaseName)
    local obj = setmetatable({}, self)
    local private = {}

    private.databaseName = databaseName
    private.data = nil
        -- Load database from file on init
    local loadedData = files.load_database(private.databaseName)
    if loadedData then
        private.data = loadedData
        log("Database '"..databaseName.."' loaded",3)
    else
        private.data = {}
        log("Database '"..databaseName.."' created",3)
    end


    function obj:getData()
        return private.data
    end

    function obj:setData(newData)
        private.data = newData
    end

	 function obj:set(key,value)
		 private.data[key] = value
         obj:save()
         return private.data[key]
	 end

	 function obj:get(key)
		 return private.data[key]
	 end

    function obj:save()
        local success = files.save_database(private.databaseName, private.data)
		if success then
			log("Database '"..private.databaseName.."' saved",3)
		else
			log("Database '"..private.databaseName.."' save failed",5)
		end
    end

	function obj:delete(key)
		if private.data[key] ~= nil then
			private.data[key] = nil
		end
		obj:save()
	end
    return obj
end

return Database

